export const AGENT_TEMPLATE: Record<string, string> = {
  "README.md": "# An agent\n\nAn agent is what a person opens: its UI, its STATE, the ICA at work in its sessions, and its programs.\n\n- `agent.json` — its title, look and starting points; its programs; where its STATE starts; and its ICA (`ica`: the\n  composer answers questions in words) with that ICA's first prompt, its `domain` — the platform's (`composer-domain`),\n  carried by the engine release, never written here. The tools are the ICA's, named by its domain.\n- `knowledge/index.mts` — the concepts its questions stand on (meaning, rules, joins, traps; never numbers). A question\n  reaches them through its intent (the intent graph), never through a domain; nothing routes a question by them.\n- `programs/<name>/` — each program, the agent's own: `manifest.json` (the STATE slice it owns: inputs a person sets,\n  fields it derives, its filters), `doc.md` (that STATE in words, for the ICA), `server/` (its functions) and `web/`\n  (its own block, from @superatom/ui). docs/program-contract.md says what a program must do.\n\nEvery step a program answers follows the step standard (DESIGN-SYSTEM.md \"A step — the standard\"), drawn by the\nframework from the answer — the program writes markdown in that order and the blocks it names:\n\n- the **filter row**: filters declared in the manifest (`package.filters`), each choice computed from the data in\n  scope by a function of the program, with its count and amount — the build refuses one without that function;\n- **KPI cards**, then **words first**: a heading and two or three plain sentences said from the data;\n- **sections, one view each**: a chart opens on its chart, its table a click away; a table section is closed to one\n  line until opened;\n- everything on the page at once.\n\nThe program here shows each piece: `group` is its filter (`groupOptions` computes the choices), `key` its drill (a bar\nor a row opened, answered by `row()` in a new block), `everyKey` and `largestKey` its next moves — **option functions**\n(`package.options`), each offering one move computed from the data, or none (docs/program-contract.md \"Options\").\nA program's views are cards in a block by default; `\"ui\": { \"as\": \"ui\" }` in its manifest draws them as an interface of\ntheir own — the whole width, laid out by the program (a dashboard). Charts: `EChart` with any ECharts option.\n\nTwo doors, one STATE: a click is an `<Intent>` op; a question in words is answered by the ICA from its intent and the\nprograms' docs — markdown with marker lines (the answer, kept as the session's answer.md, its attachments beside it) —\nand may change STATE with the same ops.\n\n`sacli agent init <name>` makes this folder; `sacli agent push <folder>` is the one step that builds it, writes it and\npublishes it — people use it at once (`--draft` to keep it unpublished).\n",
  "agent.json": "{\n  \"name\": \"example\",\n  \"title\": \"Example\",\n  \"domain\": \"composer-domain\",\n  \"programs\": [\"example\"],\n  \"ica\": \"composer\",\n  \"tools\": [],\n  \"icon\": \"lucide:layout-grid\",\n  \"accent\": \"primary\",\n  \"says\": \"What this agent is for, in one line.\",\n  \"start\": { \"example\": { \"group\": null, \"key\": null } },\n  \"starts\": [\n    { \"key\": \"all\", \"label\": \"Every key\", \"says\": \"The whole picture\", \"start\": { \"example\": { \"group\": null, \"key\": null } } }\n  ]\n}\n",
  "knowledge/index.mts": "// What the agent's questions stand on, as the composition graph imports it (`sacli agent push <folder>` imports it,\n// with the agent's programs and the agent itself): CONCEPTS — the atomic knowledge base, each thing said once. A\n// question reaches them through its intent (docs/intent-graph.md): an intent's way names the concepts it stands on, and\n// the ICA finds more with find-concept. Nothing routes a question by them, and no ICA is told them all up front: an\n// ICA's first prompt is its domain, the platform's (agent.json `domain`).\n//\n// How concepts are written: `composition-graph guide`; check before importing with `composition-graph check\n// knowledge/index.mts`. A concept is what one kind of question needs, in only the sections it needs (entity map,\n// definitions, calculation, rules, method, examples); each thing is said in one concept and the others name it in\n// `uses`. No instance — a name, an id, a number, \"today\" — outside the examples. Meaning, rules, joins and traps: never\n// numbers. The programs say in their doc.md what STATE they take, so a question in words can change STATE the same way\n// a click does.\nimport type { ConceptBody } from '@superatom/composition-graph'\n\ntype Concept = ConceptBody & { name: string }\n\n/** The organisation's decisions a program reads (a threshold, a floor), by name — each named in the reading program's\n *  manifest (\"settings\"). How it reads time, money and words is its configuration, never a setting. */\nexport const settings: { name: string; value: unknown; description: string }[] = []\n\nexport const concepts: Concept[] = [\n  {\n    name: 'example/entities-and-joins', title: 'The entities and how they join', form: 'sections',\n    sections: [{ name: 'entity map', text: 'thing ──1:n── line ──n:1── other thing\\n  key thing_id        key other_id' }],\n  },\n  {\n    name: 'example/main-figure', title: 'How the main figure is worked out', form: 'sections',\n    uses: ['example/entities-and-joins'],\n    sections: [\n      { name: 'definitions', items: ['figure = what it means, generically, or its formula'] },\n      { name: 'calculation', text: 'line → thing\\nfilter what counts · group by what it is shown by · measure sum(value)' },\n      { name: 'rules', items: ['A column that looks like one thing and is another, and how to read it.'] },\n    ],\n  },\n]\n",
  "programs/example/doc.md": "# example\n\nWhat it shows, in one line. STATE (`example`):\n\n- *Input:* `group` — one group, or null for all: the step's filter. Its choices are the groups that hold something in\n  the current scope, worked out from the data (`groupOptions`), each with how many keys it holds and their amount.\n- *Input:* `key` — one key, or null for all: set when a bar or a row is opened.\n- *Derived:* `data` — at most 100 keys for the scope in force, with the total and the count from the source, fetched\n  once per scope (`data.basis`).\n\nSet an input (a click or words) and the view is worked out again.\n\nFunctions:\n- `run` answers from the slice: the filter row, the headline figures, what stands out in words, the largest keys as\n  bars, every key as a table.\n- `row` answers a key clicked in the bars or the table: a new block below, the same view narrowed to that key.\n\nOptions (computed at each step, offered only where they hold):\n- `everyKey` — with a key opened: back to every key in scope, saying how many more there are.\n- `largestKey` — without a key opened: the key that carries a third or more of the total, opened.\n",
  "programs/example/manifest.json": "{\n  \"id\": \"prg_example\",\n  \"name\": \"example\",\n  \"version\": 1,\n  \"scope\": \"global\",\n  \"owner\": \"user:you\",\n  \"attachesTo\": \"area.topic\",\n  \"reads\": [\"datasource:SOURCE\"],\n  \"published\": false,\n  \"ui\": { \"blocks\": [\"example\"] },\n  \"package\": {\n    \"owns\": \"example\",\n    \"schema\": { \"group\": { \"nullable\": \"string\" }, \"key\": { \"nullable\": \"string\" }, \"data\": { \"nullable\": \"json\" } },\n    \"initial\": { \"group\": null, \"key\": null, \"data\": null },\n    \"reads\": [],\n    \"functions\": [{ \"name\": \"run\", \"produces\": \"view\" }, { \"name\": \"row\", \"produces\": \"view\" }],\n    \"options\": [\"everyKey\", \"largestKey\"],\n    \"filters\": [{ \"field\": \"group\", \"label\": \"Group\", \"options\": \"groupOptions\", \"size\": \"medium\", \"noun\": [\"key\", \"keys\"], \"unit\": \"count\" }],\n    \"commands\": [],\n    \"doc\": \"doc.md\"\n  }\n}\n",
  "programs/example/server/index.ts": "// The program's Node side: its functions. Each gets the whole STATE (frozen) and a context whose set() changes only this\n// program's slice; data comes only through ctx.services.query (the reader's data access is applied for you).\n//\n// STATE is inputs and derived: the person sets the inputs (here `group`, a filter, and `key`, a drill), the program\n// derives the rest. The data is fetched once per scope (`data.basis` says for which) and kept in the slice, so a run with\n// nothing new asks nothing. At most 100 rows are shown; the total and the count come from the source.\n//\n// THE STEP STANDARD (docs/program-contract.md \"The view\"): the answer is markdown in the order a step reads —\n//   **Title** — _one line_            the block frame's title and the line under it\n//   :::filters <slice>.filters        the filter row: declared in the manifest, its choices computed by groupOptions()\n//   :::kpis …                         the headline figures\n//   ## A heading, then 2–3 sentences  words first, said from the data\n//   :::bars …                         a section with a chart: it opens on the chart, its table a click away\n//   :::table …                        a section that is only a table: closed to one line until opened\n// The framework draws all of it; nothing here lays a screen out. What a program is given (query, append, who…): the\n// platform's own types (`platform/program` in a cloned project).\nimport type { OptionContext, ProgramContext } from '@superatom/program'\nimport { keysQuery, groupChoicesQuery, type Scope } from './query.js'\n\ntype Row = { key: string; value: number }\ntype Data = { basis: string; rows: Row[]; total: number; count: number }\ntype Slice = Scope & { data: Data | null }\ntype Ctx = ProgramContext<Slice>\ntype Reading = Pick<OptionContext, 'services'>\n\nconst basisOf = (s: Scope) => JSON.stringify([s.group, s.key])\nconst scopeOf = (s: Slice): Scope => ({ group: s.group, key: s.key })\n\nasync function fetchData(s: Scope, ctx: Reading): Promise<Data> {\n  const { sql, params } = keysQuery(s)\n  const got = await ctx.services.query('SOURCE', sql, params)\n  return { basis: basisOf(s), rows: got.map((r) => ({ key: String(r.key), value: Number(r.value) })), total: Number(got[0]?.total ?? 0), count: Number(got[0]?.keys ?? 0) }\n}\n\n/** The step's words: what stands out, said from the figures — two or three plain sentences, never a fixed phrase. */\nfunction reading(d: Data): string[] {\n  const top = d.rows[0]\n  if (!top || !d.total) return ['Nothing is recorded in this scope.']\n  const share = Math.round((100 * top.value) / d.total)\n  const said = [`${top.key} carries ${share}% of the total, the largest of ${d.count} key${d.count === 1 ? '' : 's'}.`]\n  const rest = d.rows.slice(1, 3).map((r) => r.key)\n  if (rest.length) said.push(`${rest.join(' and ')} come${rest.length === 1 ? 's' : ''} next; the rest share what is left.`)\n  return said\n}\n\nexport async function run(state: { example: Slice }, ctx: Ctx) {\n  const s = state.example\n  let d = s.data && s.data.basis === basisOf(scopeOf(s)) ? s.data : null\n  if (!d) { d = await fetchData(scopeOf(s), ctx); ctx.set({ data: d }) }\n  const where = [s.group, s.key].filter(Boolean).join(' · ')\n  const drill = { dim: 'key', key: 'key', label: 'label' }\n  const blocks = {\n    'example-kpis': { type: 'kpis', items: [\n      { label: 'Total', value: d.total, unit: 'count', hint: where ? `for ${where}` : 'every key' },\n      { label: 'Keys', value: d.count, unit: 'count', hint: d.count > d.rows.length ? `the largest ${d.rows.length} shown` : 'all shown' },\n    ] },\n    'example-bars': { type: 'bars', title: 'The largest keys', says: 'Open one to narrow to it', axis: 'key', unit: 'count',\n      series: [{ key: 'value', label: 'Amount' }], rows: d.rows.slice(0, 12).map((r) => ({ label: r.key, key: r.key, values: { value: r.value } })), rowMove: drill },\n    'example-table': { type: 'table', title: 'Every key', says: 'Open one to narrow to it', rowMove: { dim: 'key', key: 'key', label: 'key' },\n      columns: [{ key: 'key', label: 'Key' }, { key: 'value', label: 'Amount', unit: 'count' }], rows: d.rows },\n  }\n  const markdown = [\n    `**Example** — _${d.count} keys${where ? ` in ${where}` : ''}, ${d.total} in total_`,\n    ':::filters example.filters',\n    ':::kpis example-kpis',\n    '## What stands out',\n    reading(d).join(' '),\n    ':::bars example-bars',\n    ':::table example-table',\n  ].join('\\n\\n')\n  return { answer: { markdown, blocks } }\n}\n\n// ── The filter's choices ─────────────────────────────────────────────────────────────────────────────────────────────\n// Named in the manifest (`package.filters[].options`): the platform calls it after every answer, with the STATE as the\n// run left it and services that only read, and draws the row. It returns the choices that hold something in the current\n// scope — each with how many keys it holds and their amount — so no choice can give an empty view. Never a list typed\n// here or in the manifest: the build refuses one.\n\n/** The groups to choose from, in the scope the drill leaves. */\nexport async function groupOptions(state: { example: Slice }, ctx: Reading) {\n  const { sql, params } = groupChoicesQuery(scopeOf(state.example))\n  const got = await ctx.services.query('SOURCE', sql, params)\n  return got.filter((r) => Number(r.count) > 0).map((r) => ({ value: String(r.value), label: String(r.value), count: Number(r.count), amount: Number(r.amount) }))\n}\n\n// ── Options: the next moves this program offers at a step ───────────────────────────────────────────────────────────\n// Each option is a function, listed in the manifest's `package.options`. It is given the step — the whole STATE (frozen),\n// ctx.context (what the session was started with), ctx.history (its answers down to here) — and services that only\n// read. It works out whether its move makes sense HERE, from what is there, and returns it — a label said from the data,\n// and one of this program's functions to call or ops on its own slice — or null: then nothing is offered. It never does\n// the work itself and changes nothing; it is quick (a time limit applies). A fixed list of moves is not an option.\n\n/** With a key opened: the way back to every key in scope, saying how many more there are. */\nexport async function everyKey(state: { example: Slice }, ctx: OptionContext) {\n  const s = state.example\n  if (!s.key || !s.data) return null\n  const { sql, params } = keysQuery({ group: s.group, key: null })\n  const [all] = await ctx.services.query('SOURCE', sql, params)\n  const more = Number(all?.keys ?? 0) - 1\n  return more > 0 ? { label: `Every key — ${more} more besides ${s.key}`, ops: [{ op: 'set' as const, path: 'example.key', value: null }], to: 'current' as const } : null\n}\n\n/** Without a key opened: the key that carries most of the total, when one does (a third or more of it). */\nexport function largestKey(state: { example: Slice }) {\n  const d = state.example.data\n  const top = d?.rows[0]\n  if (state.example.key || !d || !top || !d.total || top.value / d.total < 1 / 3) return null\n  return { label: `${top.key}: ${Math.round((100 * top.value) / d.total)}% of the total`, call: { fn: 'row', params: { row: { key: top.key } } }, to: 'new' as const }\n}\n\n/** A key clicked (a bar or a row): the new block below it, narrowed to that key (a call does not re-run its own program). */\nexport async function row(state: { example: Slice }, ctx: Ctx) {\n  const key = String(((ctx.params.row ?? {}) as Record<string, unknown>).key ?? '')\n  if (!key) return run(state, ctx)\n  ctx.set({ key })\n  return run({ ...state, example: { ...state.example, key } }, ctx)\n}\n",
  "programs/example/server/query.ts": "// The rules, once, as queries the source runs. Totals and counts are worked out by the source over every row in scope\n// (window functions run before the limit), never by adding up the rows shown; at most 100 rows come back.\n\n/** What the view narrows by: the group a person chose (a filter), the key a click opened (a drill). */\nexport type Scope = { group: string | null; key: string | null }\n\nconst where = (s: Partial<Scope>) => {\n  const parts = [s.group ? 'grp = @group' : '', s.key ? 'key = @key' : ''].filter(Boolean)\n  return { sql: parts.length ? ` WHERE ${parts.join(' AND ')}` : '', params: { ...(s.group ? { group: s.group } : {}), ...(s.key ? { key: s.key } : {}) } }\n}\n\n/** Every key in scope, largest first: its amount, with the total and the number of keys in scope. */\nexport function keysQuery(s: Scope): { sql: string; params: Record<string, unknown> } {\n  const w = where(s)\n  return {\n    sql: `SELECT key, SUM(amount) AS value, SUM(SUM(amount)) OVER () AS total, COUNT(*) OVER () AS keys\n          FROM some_table${w.sql}\n          GROUP BY key ORDER BY value DESC LIMIT 100`,\n    params: w.params,\n  }\n}\n\n/** The groups a person can choose, in the scope the other narrowings leave (never the group itself): each with how many\n *  keys it holds and their amount — only groups that hold something, so no choice gives an empty view. */\nexport function groupChoicesQuery(s: Scope): { sql: string; params: Record<string, unknown> } {\n  const w = where({ key: s.key })\n  return {\n    sql: `SELECT grp AS value, COUNT(DISTINCT key) AS count, SUM(amount) AS amount\n          FROM some_table${w.sql}\n          GROUP BY grp HAVING COUNT(*) > 0 ORDER BY amount DESC LIMIT 100`,\n    params: w.params,\n  }\n}\n",
  "programs/example/web/index.tsx": "// The program's React side: one export per ui block, named in PascalCase (block \"example\" → Example), drawn with\n// { slice, state } beside the step's answer. Most of a step is the framework's, drawn from the answer: the filter row\n// (declared in the manifest, its choices computed on the server), the figures, the words, the sections — so a block of\n// the program's own holds only what is its own. Controls are <Intent>s — the one way a screen changes STATE: one that\n// narrows the same view changes it in place (to=\"current\", the default); one that opens another view or records a\n// decision opens a new block (to=\"new\"). A value a person picks is always one the data offers — never typed into a box.\n// Build from the framework (@superatom/ui): what it lacks goes into the framework, not into one program.\nimport { Intent, ActionBar } from '@superatom/ui'\n\ntype Slice = { group: string | null; key: string | null }\n\n/** With a key opened: the way back to every key, in place. */\nexport function Example({ slice }: { slice?: Slice }) {\n  if (!slice?.key) return null\n  return (\n    <ActionBar>\n      <Intent ops={[{ op: 'set', path: 'example.key', value: null }]} className=\"sa-btn\">Every key</Intent>\n    </ActionBar>\n  )\n}\n"
}
